<script setup>
import {ref,computed,onMounted,defineAsyncComponent} from 'vue'
import {useArcade} from '../stores/arcade'
import {useLearning} from '../stores/learning'
import {formatTime} from '../lib/api'
import PointHistory from '../components/PointHistory.vue'
import SourceStats from '../components/SourceStats.vue'
import PartnerImage from '../components/PartnerImage.vue'
const LearningCharts=defineAsyncComponent(()=>import('../components/LearningCharts.vue'))
const arcade=useArcade(),study=useLearning(),selected=ref('vue'),current=computed(()=>study.catalog.find(s=>s.id===selected.value));onMounted(()=>study.load())
</script>
<template><section class="trainer-page"><p v-if="study.error" class="notice" role="alert">{{study.error}}</p><p v-if="arcade.data.legacyMigration?.status==='pending'" class="notice">기존 {{arcade.data.legacyMigration.coins}}코인 이전 승인 대기 중</p><section class="trainer-card" :data-partner="arcade.partner.id"><div class="trainer-card-top"><span>내 학습 / TRAINER PASS</span><h1>Spokemon TRAINER CARD</h1></div><div class="trainer-card-body"><div class="trainer-portrait"><span class="trainer-id">ID / {{arcade.user.login}}</span><PartnerImage size="hero"/><div class="trainer-partner-name">{{arcade.partner.name}} <b>Lv.{{arcade.level}}</b></div><span class="trainer-status">● 모험을 준비하는 중</span></div><div class="trainer-info"><h2>{{arcade.user.nickname}}</h2><dl><div><dt>기수</dt><dd>{{arcade.user.className}}</dd></div><div><dt>오늘 공부</dt><dd>{{formatTime(study.stats.todaySeconds)}}</dd></div><div><dt>누적 공부</dt><dd>{{formatTime(study.stats.totalSeconds)}}</dd></div><div><dt>공개 진도</dt><dd>{{study.stats.completed??0}} / {{study.stats.total??0}} · {{study.stats.percent??0}}%</dd></div><div><dt>복습 필요</dt><dd>{{study.stats.pending??0}}문제</dd></div></dl><div class="trainer-badges"><div><span>🪙</span><b>{{arcade.data.coins.toLocaleString()}}</b><small>POINTS</small></div><RouterLink to="/quiz"><span>✦</span><b>퀴즈 타임</b><small>START QUEST →</small></RouterLink><RouterLink to="/pet/mistakes"><span>▤</span><b>틀린 문제!</b><small>REVIEW →</small></RouterLink></div></div></div><div class="trainer-card-bottom"><span>작은 배움이 모여 레벨 업!</span><button class="text-button" @click="study.load">↻ 기록 새로고침</button></div></section><PointHistory/><SourceStats/><LearningCharts :rows="study.catalog.map(s=>({...s,totalSeconds:(study.stats.subjectTimes?.find(t=>t.subject===s.id)?.ms??0)/1000}))" title="과목별 학습 차트"/><section class="panel trainer-curriculum"><div class="trainer-section-heading"><h2>학습 퀘스트</h2><span>공개된 학습 항목부터 도전하세요</span></div><div class="trainer-subject-tabs"><button v-for="s in study.catalog" :key="s.id" :class="{selected:selected===s.id}" @click="selected=s.id">{{s.name}}<small>{{s.completed}}/{{s.total}}</small></button></div><article v-if="current" class="unit-subject"><h3>{{current.name}} · {{current.percent}}%</h3><progress :value="current.completed" :max="current.total||1"/><div class="unit-grid"><div v-for="unit in current.units" :key="unit.number" class="unit-tile" :class="{locked:unit.locked}"><b>{{unit.locked?'🔒':'▣'}} {{unit.title}}</b><span>학습 항목 {{unit.total}}개</span><p v-if="unit.locked">아직 배우지 않은 단원입니다</p><template v-else><small>{{unit.completed}} / {{unit.total}} 완료</small><RouterLink :to="'/learn/'+current.id+'/'+unit.number" class="button light">학습하기</RouterLink></template></div></div></article><p class="chart-note">진행률은 공개된 학습 항목 중 완료한 비율입니다. 공개 항목이 없으면 0%로 표시합니다.</p></section></section></template>
